async function checkChatUnread(user,projects){
  try{
    const r=await fetch(_SU+"/rest/v1/messages?select=channel,created_at&order=created_at.desc&limit=300",{headers:_SH});
    if(!r.ok)return false;
    const rows=await r.json();
    const latestByChannel={};
    rows.forEach(m=>{if(!latestByChannel[m.channel]||m.created_at>latestByChannel[m.channel])latestByChannel[m.channel]=m.created_at;});
    const accessible=user.role==="site_engineer"?projects.filter(p=>(p.assigned_engineers||[]).includes(user.email)):user.role==="project_manager"?projects.filter(p=>p.assigned_pm===user.email):projects;
    const channels=["general",...accessible.map(p=>"project:"+p.id)];
    return channels.some(ch=>{
      const latest=latestByChannel[ch];
      if(!latest)return false;
      const seen=getLastSeenChat(user.id,ch);
      return !seen||latest>seen;
    });
  }catch(e){return false;}
}
