const sameName=(a,b)=>(a||"").trim().toLowerCase()===(b||"").trim().toLowerCase();
const calcScore=(name,projects,bonusData={},leadEvents=[],email=null)=>{
  const mk=monthKey();
  // Only count tasks completed THIS month
  const tasks=projects.flatMap(allT).filter(t=>{
    if(!sameName(t.assigned_to,name)||t.status!=="Completed")return false;
    if(!t.actual_end)return false;
    return t.actual_end.slice(0,7)===mk;
  });
  let score=0;
  tasks.forEach(t=>{
    const base={High:15,Medium:10,Low:7}[t.priority]||10;
    let bonus=5;
    if(t.actual_end&&t.end_date){
      const diff=Math.round((new Date(t.actual_end)-new Date(t.end_date))/86400000);
      if(diff<0)bonus=12;else if(diff===0)bonus=8;else if(diff<=3)bonus=2;else if(diff<=7)bonus=0;else bonus=-3;
    }
    score+=Math.max(0,base+bonus);
  });
  // Add admin bonus for this month
  const key=`${name}__${mk}`;
  const adminBonus=(bonusData[key]||[]).reduce((s,b)=>s+(b.points||0),0);
  // Add sales/CRM points for this month
  const salesPts=(leadEvents||[]).filter(e=>{
    const matches=email?(e.owner_email||"").toLowerCase()===email.toLowerCase():sameName(e.owner_name,name);
    if(!matches)return false;
    if(!e.created_at)return false;
    return e.created_at.slice(0,7)===mk;
  }).reduce((s,e)=>s+(Number(e.points)||0),0);
  return{taskPts:score,bonusPts:adminBonus,salesPts,total:score+adminBonus+salesPts};
};
const mStats=(name,projects)=>{const tasks=projects.flatMap(allT).filter(t=>sameName(t.assigned_to,name));const done=tasks.filter(t=>t.status==="Completed");const onTime=done.filter(t=>!t.delay_days||t.delay_days<=0).length;return{total:tasks.length,done:done.length,onTime,delayed:tasks.filter(t=>t.delay_days>0).length,high:done.filter(t=>t.priority==="High").length,pct:done.length?Math.round(onTime/done.length*100):0};};
