async function syncBOQDB(items){try{const rows=(items||[]).map(b=>({project_id:parseInt(b.project_id,10),item_number:String(b.item_code||"-").trim()||"-",description:String(b.description||"-").trim()||"-",unit:b.unit||null,quantity:Number(b.quantity)||0,msr_rate:Number(b.msr_rate)||0,index_factor:Number(b.index_factor)||1,unit_rate:Number(b.rate)||0,boq_type:b.boq_type||null,category:b.boq_type||null})).filter(r=>r.project_id>0);console.log("syncBOQ saving",rows.length,"rows");if(rows.length===0)return true;const pids=[...new Set(rows.map(r=>r.project_id))];for(const pid of pids){await fetch(_SU+"/rest/v1/boq_items?project_id=eq."+pid,{method:"DELETE",headers:{..._SH,"Prefer":"return=minimal"}});}const post=await fetch(_SU+"/rest/v1/boq_items",{method:"POST",headers:{..._SH,"Prefer":"return=minimal"},body:JSON.stringify(rows)});if(!post.ok){const t=await post.text();console.error("BOQ POST failed",post.status,t);alert("Save failed: "+post.status+" "+t);return false;}return true;}catch(e){console.error("syncBOQ:",e);alert("Save error: "+e.message);return false;}}
async function syncExpDB(exps){
  try{
    const today=new Date().toISOString().slice(0,10);
    const rows=(exps||[]).filter(e=>e.project_id!=null).map(e=>({project_id:Number(e.project_id),item_number:(e.item_code||null),category:(e.category||"General"),description:e.description||null,vendor:e.payee||null,amount:Number(e.debit)||0,expense_date:e.date||today,sl_number:e.sl||null,ml_flag:(e.ml||"M"),payee:e.payee||null,remarks:e.remarks||null}));
    if(rows.length===0){console.warn("syncExp: refusing to run - empty rows would wipe data with no replacement");return false;}
    const pids=[...new Set(rows.map(r=>r.project_id))];
    for(const pid of pids){
      await fetch(_SU+"/rest/v1/site_expenses?project_id=eq."+pid,{method:"DELETE",headers:{..._SH,"Prefer":"return=minimal"}});
    }
    const post=await fetch(_SU+"/rest/v1/site_expenses",{method:"POST",headers:{..._SH,"Prefer":"return=minimal"},body:JSON.stringify(rows)});
    if(!post.ok){const t=await post.text();console.error("Expenses POST failed",post.status,t);return false;}
    return true;
  }catch(e){console.error("syncExp:",e);return false;}
}
async function createProjectDB(d,region){try{const row={name:d.name||d.title||"Untitled",code:d.code||null,location:d.location||null,client_name:d.client_name||d.client||null,project_type:d.project_type||d.type||null,start_date:d.start_date||null,end_date:d.end_date||null,region_id:(region&&region.db_id)||d.region_id||null,project_manager:d.project_manager||d.pm||null,assigned_pm:d.assigned_pm||d.pm||null,status:d.status||"active"};const r=await fetch(_SU+"/rest/v1/projects",{method:"POST",headers:{..._SH,"Prefer":"return=representation"},body:JSON.stringify(row)});if(!r.ok)return null;const j=await r.json();return Array.isArray(j)?j[0]:j;}catch(e){console.error("createProjectDB:",e);return null;}}
