async function saveLeadDB(lead,user,members){try{const owner=lead.assigned_to||user.email;let mgr=null;if(user.role==="sales_exec"){const me=(members||[]).find(m=>m.email===user.email);mgr=(me&&me.manager_email)||null;}else if(user.role==="sales_manager"){mgr=user.email;}const body={lead_key:String(lead.id),name:lead.client_name||lead.name||"Lead",company:lead.company||null,contact_phone:lead.phone||null,contact_email:lead.email||null,location:lead.location||null,source:lead.source||null,stage:lead.stage||"new",value:0,notes:lead.brief||null,owner_email:owner,owner_name:lead.owner_name||user.name||null,owner_role:user.role||null,manager_email:mgr,next_contact:lead.next_contact||null,data:lead};const r=await fetch(_SU+"/rest/v1/leads?on_conflict=lead_key",{method:"POST",headers:{..._SH,"Prefer":"resolution=merge-duplicates,return=minimal"},body:JSON.stringify(body)});return r.ok;}catch(e){console.error("saveLead:",e);return false;}}
