async function registerDB(d){
  try{
    // create employee first to get an id
    const empBody={name:d.name,email:d.email,role:d.role,designation:d.department||d.role,status:'pending'};
    const er=await fetch(_SU+"/rest/v1/employees",{method:"POST",headers:{..._SH,"Prefer":"return=representation"},body:JSON.stringify(empBody)});
    if(!er.ok){return {ok:false,err:'emp '+er.status};}
    const emp=(await er.json())[0];
    const eid=emp&&emp.id;
    // user_profiles (mirror), is_active false = pending
    await fetch(_SU+"/rest/v1/user_profiles",{method:"POST",headers:{..._SH,"Prefer":"return=minimal"},body:JSON.stringify({employee_id:eid,email:d.email,role:d.role,is_active:false})}).catch(()=>{});
    // users (login record) with bcrypt via rpc-less insert: store plain? No—use login_rpc expects hash. Use signup rpc if present.
    const ur=await fetch(_SU+"/rest/v1/rpc/mone_register",{method:"POST",headers:{..._SH},body:JSON.stringify({p_email:d.email,p_password:d.password,p_role:d.role,p_employee_id:eid})});
    if(!ur.ok){return {ok:true,emp:emp,warn:'user '+ur.status};}
    return {ok:true,emp:emp};
  }catch(e){return {ok:false,err:String(e)};}
}
async function approveEmpDB(empId){await fetch(_SU+"/rest/v1/users?employee_id=eq."+empId,{method:"PATCH",headers:{..._SH,"Prefer":"return=minimal"},body:JSON.stringify({is_active:true})});await fetch(_SU+"/rest/v1/user_profiles?employee_id=eq."+empId,{method:"PATCH",headers:{..._SH,"Prefer":"return=minimal"},body:JSON.stringify({is_active:true})});}
async function deleteEmployeeDB(empId){
  try{
    await fetch(_SU+"/rest/v1/activity_logs?employee_id=eq."+empId,{method:"DELETE",headers:{..._SH,"Prefer":"return=minimal"}});
    await fetch(_SU+"/rest/v1/projects?created_by=eq."+empId,{method:"PATCH",headers:{..._SH,"Prefer":"return=minimal"},body:JSON.stringify({created_by:null})});
    await fetch(_SU+"/rest/v1/user_profiles?employee_id=eq."+empId,{method:"DELETE",headers:{..._SH,"Prefer":"return=minimal"}});
    await fetch(_SU+"/rest/v1/users?employee_id=eq."+empId,{method:"DELETE",headers:{..._SH,"Prefer":"return=minimal"}});
    const r=await fetch(_SU+"/rest/v1/employees?id=eq."+empId,{method:"DELETE",headers:{..._SH,"Prefer":"return=minimal"}});
    return r.ok;
  }catch(e){console.error("delEmp:",e);return false;}
}
