  const ago=(ts)=>{const d=new Date(ts),now=new Date(),m=Math.floor((now-d)/60000);if(m<1)return"just now";if(m<60)return m+"m ago";const h=Math.floor(m/60);if(h<24)return h+"h ago";const dy=Math.floor(h/24);if(dy<7)return dy+"d ago";return d.toLocaleDateString("en-IN",{day:"2-digit",month:"short"});};
