            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,alignItems:"center"}}>
              <div style={{height:isMobile?130:180}}><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={pp} cx="50%" cy="50%" innerRadius={isMobile?34:50} outerRadius={isMobile?56:80} paddingAngle={3} dataKey="value">{pp.map((e,i)=><Cell key={i} fill={e.color}/>)}</Pie><Tooltip contentStyle={{background:C.card,border:`1px solid ${C.b}`,borderRadius:8,fontSize:11}}/></PieChart></ResponsiveContainer></div>
              <div>{pp.map((d,i)=><div key={i} style={{display:"flex",alignItems:"center",gap:6,marginBottom:5}}><div style={{width:8,height:8,borderRadius:2,background:d.color}}/><span style={{fontSize:11,color:C.s,flex:1}}>{d.name}</span><span style={{fontFamily:"'Rajdhani',sans-serif",fontWeight:700,fontSize:12,color:C.t}}>{d.value}</span></div>)}</div>
            </div>
