async function loadPaymentsAllDB(){try{const r=await fetch(_SU+"/rest/v1/payments?select=project_id,amount,approved",{headers:_SH});if(!r.ok)return[];return await r.json();}catch(e){return[];}}
async function loadMeetingsDB(){try{const r=await fetch(_SU+"/rest/v1/meetings?select=*&order=meeting_date.asc,meeting_time.asc",{headers:_SH});if(!r.ok)return[];return await r.json();}catch(e){return[];}}
async function addMeetingDB(m){try{const r=await fetch(_SU+"/rest/v1/meetings",{method:"POST",headers:{..._SH,"Prefer":"return=representation"},body:JSON.stringify(m)});if(!r.ok)return null;const rows=await r.json();return rows&&rows[0]?rows[0]:null;}catch(e){return null;}}
