async function loadAssetsDB(){try{const r=await fetch(_SU+"/rest/v1/assets?select=*&order=created_at.desc",{headers:_SH});if(!r.ok)return[];return await r.json();}catch(e){return[];}}
async function addAssetDB(a){try{const r=await fetch(_SU+"/rest/v1/assets",{method:"POST",headers:{..._SH,"Prefer":"return=representation"},body:JSON.stringify(a)});if(!r.ok)return null;const rows=await r.json();return rows&&rows[0]?rows[0]:null;}catch(e){return null;}}
