        <div style={{textAlign:"right"}}><div style={{fontSize:18,fontWeight:700,color:"#1c1917"}}>PROJECT REPORT</div><div style={{fontSize:11,color:"#78716c",marginTop:2}}>Generated: {genDate}</div><div style={{fontSize:11,color:"#78716c"}}>Ref: {p.code}</div></div>
